options.css:
@keyframes pb-spin {
    0% {
		transform: rotate(360deg);
	}

    100% {
		transform: rotate(0deg);
	}
}

.pb-circleLoader-wrapper {
	width: 30px;
	height: 30px;
	border-radius: 50%;
	position: relative;
	overflow: hidden;
	text-align: left;
	animation: pb-spin 2s linear infinite;
}

.pb-circleLoader-inside {
	width: 100%;
	height: 50%;
	position: relative;
	margin-top: 50%;
	background: linear-gradient(90deg, rgb(220, 220, 220), rgb(150, 150, 150));
}

.pb-circleLoader-inside:before {
	content: '';
	width: 100%;
	height: 100%;
	position: absolute;
	margin-top: -50%;
	background: linear-gradient(90deg, rgb(50, 50, 50), rgb(160, 160, 160));
}

.pb-circleLoader-inside:after {
	content: '';
	width: 80%;
	height: 160%;
	position: absolute;
	margin-top: -40%;
	margin-left: 10%;
	background: white;
	border-radius: 50%;
}

.bannerContainer {
	display: flex;
	align-items: center;
	justify-content: center;
}

.bannerMainTitle {
	text-align: left;
}

#bannerScore {
	border-radius: 8px;
	font-size: 30pt;
	color: white;
	background-color: white;
	width: 60px;
	height: 60px;
	display: flex;
	align-items: center;
	justify-content: center;
	margin-right: 20px;
}
